    /**
     * Obtener un listado de los datos de los conceptos de percepción y descuento.
     *
     * @param int $inicio Inicio de la busqueda.
     * @param int $limite Limite maximo de la busqueda.
     * @return array    Listado de los datos de los conceptos de percepción y descuento.
     */
    public static function obtenerListadoConceptosPD ($inicio = 0, $limite = 10, $criterio)
    {

        $where = (!empty($criterio)) ? "c.denominacion ilike '%".$criterio."%'" : 'c.denominacion is not null';
        //Devolviendo el listado de los conceptos de percepción y descuento en forma de arreglo.
        return Doctrine_Query::create()
            ->select('c.idconceptopercepciondescuento, c.abreviatura, c.denominacion,
                    c.fechainicio, c.fechafin, c.descripcion, c.idtipoconceptopd as idtipoconceptopd, 
                    tc.denominacion as tipoconcepto')
            ->from('NomConceptoPercepcionDescuento c')
            ->leftjoin('c.NomTipoConceptoPD tc')
            ->innerJoin('')
            ->where($where)
            ->limit($limite)
            ->offset($inicio)
            ->fetchArray();
    }

