        $conn = Doctrine_Manager:: connection();
        $sql = "SELECT c.idconceptopercepciondescuento, c.abreviatura, c.denominacion,
                    c.fechainicio, c.fechafin, c.descripcion,em.idexpresionmatematica,
                    c.idtipoconceptopd as idtipoconceptopd,
                    m2.denominacion as tipoconcepto,c.esdescuentoaplicarunaves,em.expresionamostrar
                            FROM mod_nomina.nom_conceptopercepciondescuento c
                            LEFT JOIN mod_nomina.nom_tipoconceptopercepciondescuento m2 ON c.idtipoconceptopd = m2.idtipoconceptopd
                            LEFT JOIN mod_utiles.dat_expresionmatematica em ON
                            em.idexpresionmatematica = c.formulaaplicardescuentounaves";
        $result = $conn->execute($sql . $where . $limit)->fetchAll();

        return $result;
    }

