    /**
     * Obtener la lista de los conceptos de percepción y descuento, ya sea para obtener los datos del mismo,
     * o listarlos segun un rango definido, así como filtrandolo por un criterio de búsqueda
     *
     * @param null $idconcepto , Identificador del concepto
     * @param int $start , A partir de que posición se desean los valores
     * @param int $limit , Cuantos valores de retorno maximo deben haber
     * @param string $busqueda , Criterio de comparación para la denominacion y la abreviatura
     *
     * @return array
     */
    public static function obtenerListadoTodosConceptosPD ($idconcepto = null, $start = 0, $limit = 0, $busqueda = '')
    {

        //Devolviendo el listado de los conceptos de percepción y descuento en forma de arreglo.

        $query = Doctrine_Query::create()
            ->select('c.idconceptopercepciondescuento as id, c.idconceptopercepciondescuento,
                               c.abreviatura, c.denominacion,
                    c.fechainicio, c.fechafin, c.descripcion, c.idtipoconceptopd as idtipoconceptopd')
            ->from('NomConceptoPercepcionDescuento c')->orderBy('c.denominacion');
        if($idconcepto){
            if(is_array($idconcepto)){
                $idconcepto = implode(',', $idconcepto);
                $query->addWhere("c.idconceptopercepciondescuento IN ($idconcepto)");
            }else{
                $query->addWhere('c.idconceptopercepciondescuento = ?', $idconcepto);
            }
        }
        if(is_numeric($start)){
            $query->offset($start);
        }
        if($limit){
            $query->limit($limit);
        }
        if($busqueda){
            $query->addWhere("((c.abreviatura ILIKE '%$busqueda%') OR (c.denominacion ILIKE '%$busqueda%'))");
        }
        $result = $query->fetchArray();
        return $result;
    }

