    public static function existeDenominacionConcepto ($denominacion, $idconceptopd = false)
    {

        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        if(!$idconceptopd){
            $result = $query->from('NomConceptoPercepcionDescuento p')
                ->where("p.denominacion=?", array($denominacion))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
        }else{
            $result = $query->from('NomConceptoPercepcionDescuento p')
                ->where("p.denominacion=?", array($denominacion))
                ->AddWhere("p.idconceptopercepciondescuento <> ?", array($idconceptopd))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
        }


        if(count($result)){
            return 1;
        }else{
            return 0;
        }
    }

